import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BfI5QxtK.js";const u=JSON.parse('{"title":"Launch feedback","description":"","frontmatter":{},"headers":[],"relativePath":"launch-feedback.md","filePath":"launch-feedback.md"}'),n={name:"launch-feedback.md"};function h(l,e,o,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="launch-feedback" tabindex="-1">Launch feedback <a class="header-anchor" href="#launch-feedback" aria-label="Permalink to &quot;Launch feedback&quot;">​</a></h1><p>Show a busy cursor while an application starts. This API supplies feedback; it does not launch the application.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Launch feedback is built into the Gnoblin session. The CLI and shell clients can use it without installing a user script.</p><p>It uses the compositor&#39;s themed wait cursor. Application focus is unchanged.</p><h2 id="use-the-cli" tabindex="-1">Use the CLI <a class="header-anchor" href="#use-the-cli" aria-label="Permalink to &quot;Use the CLI&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> begin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> org.gnome.Nautilus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3000</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gnoblinctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> end</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example</span></span></code></pre></div><p>Here <code>example</code> is your request token, <code>org.gnome.Nautilus</code> identifies Files, and <code>3000</code> sets a three-second timeout. The commands alone show and clear the busy cursor; they do not open Files.</p><p>Wait for <code>begin</code> to return before launching the app. Use a unique token for each launch and call <code>end</code> if launch fails.</p><p>Requests end when a matching window appears or gains focus, on explicit end, or after the timeout. Overlapping requests keep the cursor busy until all end.</p><h2 id="d-bus-api" tabindex="-1">D-Bus API <a class="header-anchor" href="#d-bus-api" aria-label="Permalink to &quot;D-Bus API&quot;">​</a></h2><p>Name/interface: <code>org.gnoblin.LaunchFeedback</code>. Object: <code>/org/gnoblin/LaunchFeedback</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Arguments</th><th>Result</th></tr></thead><tbody><tr><td><code>Begin</code></td><td>Token, app hint, timeout in ms</td><td>Start feedback</td></tr><tr><td><code>End</code></td><td>Token</td><td>End feedback; unknown token is harmless</td></tr><tr><td><code>GetState</code></td><td>None</td><td>JSON count, visibility and artwork source</td></tr></tbody></table><p>Timeouts are bounded to 100–10000 ms. The app hint may be a desktop ID, WM class, GTK application ID or desktop name.</p><p>Requests expire even if a launcher exits before sending <code>End</code>. The cursor override is also released when the Gnoblin session shuts down.</p><h2 id="test" tabindex="-1">Test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;Test&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_TEST_DBUS_CLIENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tests/test-launch-feedback.py&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scripts/run-gnome-shell.sh</span></span></code></pre></div><p>Checks pointer output, overlapping requests, expiry, reload and window-map completion.</p>`,18)])])}const k=a(n,[["render",h]]);export{u as __pageData,k as default};
